--
-- Name: coach_records; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.coach_records AS
 WITH snap AS (
         SELECT DISTINCT ON (coach_seasons.coach_id) coach_seasons.id,
            coach_seasons.coach_id,
            coach_seasons.team_id,
            coach_seasons.season,
            coach_seasons.career_wins,
            coach_seasons.career_losses,
            coach_seasons.career_ties,
            coach_seasons.winning_seasons,
            coach_seasons.playoff_wins,
            coach_seasons.playoff_losses,
            coach_seasons.super_bowl_wins,
            coach_seasons.super_bowl_losses
           FROM public.coach_seasons
          ORDER BY coach_seasons.coach_id, coach_seasons.season DESC
        ), team_games AS (
         SELECT g.season,
            g.game_type,
            t.team_id,
                CASE
                    WHEN (t.score > t.opp) THEN 1
                    ELSE 0
                END AS win,
                CASE
                    WHEN (t.score < t.opp) THEN 1
                    ELSE 0
                END AS loss,
                CASE
                    WHEN (t.score = t.opp) THEN 1
                    ELSE 0
                END AS tie
           FROM (public.games g
             CROSS JOIN LATERAL ( VALUES (g.home_team_id,g.home_score,g.away_score), (g.away_team_id,g.away_score,g.home_score)) t(team_id, score, opp))
          WHERE ((g.status)::text = 'COMPLETED'::text)
        ), coached AS (
         SELECT s_1.coach_id,
            tg.season,
            tg.game_type,
            tg.team_id,
            tg.win,
            tg.loss,
            tg.tie
           FROM ((snap s_1
             JOIN public.coach_tenures ct ON ((ct.coach_id = s_1.coach_id)))
             JOIN team_games tg ON (((tg.team_id = ct.team_id) AND (tg.season > s_1.season) AND (tg.season >= ct.start_season) AND (tg.season <= COALESCE(ct.end_season, 9999)))))
        ), reg AS (
         SELECT coached.coach_id,
            coached.season,
            sum(coached.win) AS w,
            sum(coached.loss) AS l,
            sum(coached.tie) AS t,
            count(*) AS games
           FROM coached
          WHERE ((coached.game_type)::text = 'REGULAR_SEASON'::text)
          GROUP BY coached.coach_id, coached.season
        ), add AS (
         SELECT c_1.coach_id,
            sum(c_1.win) FILTER (WHERE ((c_1.game_type)::text = 'REGULAR_SEASON'::text)) AS w,
            sum(c_1.loss) FILTER (WHERE ((c_1.game_type)::text = 'REGULAR_SEASON'::text)) AS l,
            sum(c_1.tie) FILTER (WHERE ((c_1.game_type)::text = 'REGULAR_SEASON'::text)) AS t,
            sum(c_1.win) FILTER (WHERE ((c_1.game_type)::text <> 'REGULAR_SEASON'::text)) AS pw,
            sum(c_1.loss) FILTER (WHERE ((c_1.game_type)::text <> 'REGULAR_SEASON'::text)) AS pl,
            sum(c_1.win) FILTER (WHERE ((c_1.game_type)::text = 'SUPER_BOWL'::text)) AS sbw,
            sum(c_1.loss) FILTER (WHERE ((c_1.game_type)::text = 'SUPER_BOWL'::text)) AS sbl
           FROM coached c_1
          GROUP BY c_1.coach_id
        )
 SELECT c.id AS coach_id,
    c.coach_name,
    s.season AS snapshot_season,
    (s.career_wins + COALESCE(a.w, (0)::bigint)) AS career_wins,
    (s.career_losses + COALESCE(a.l, (0)::bigint)) AS career_losses,
    (s.career_ties + COALESCE(a.t, (0)::bigint)) AS career_ties,
    (s.winning_seasons + ( SELECT count(*) AS count
           FROM reg r
          WHERE ((r.coach_id = c.id) AND (r.games >= 17) AND (r.w > r.l)))) AS winning_seasons,
    (s.playoff_wins + COALESCE(a.pw, (0)::bigint)) AS playoff_wins,
    (s.playoff_losses + COALESCE(a.pl, (0)::bigint)) AS playoff_losses,
    (s.super_bowl_wins + COALESCE(a.sbw, (0)::bigint)) AS super_bowl_wins,
    (s.super_bowl_losses + COALESCE(a.sbl, (0)::bigint)) AS super_bowl_losses
   FROM ((public.coaches c
     JOIN snap s ON ((s.coach_id = c.id)))
     LEFT JOIN add a ON ((a.coach_id = c.id)));


