--
-- Name: COLUMN record_categories.coverage; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.record_categories.coverage IS 'FULL: every franchise''s season record and the NFL top 10 through 2025 are seeded. BOOK: only what the league''s record book lists (2026 on).';


--
-- Name: franchise_records_current; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.franchise_records_current AS
 SELECT fr.id,
    fr.team_id,
    fr.category,
    fr.value,
    fr.holder,
    fr.player_id,
    fr.season,
    fr.source,
    fr.created_at,
    c.label,
    c.scope,
    c.subject,
    c.better,
    c.season_type
   FROM (public.franchise_records fr
     JOIN public.record_categories c ON (((c.category)::text = (fr.category)::text)))
  WHERE (fr.value = ( SELECT
                CASE
                    WHEN ((c.better)::text = 'LOW'::text) THEN min(x.value)
                    ELSE max(x.value)
                END AS max
           FROM public.franchise_records x
          WHERE ((x.team_id = fr.team_id) AND ((x.category)::text = (fr.category)::text))));


ALTER TABLE public.franchise_records_current OWNER TO postgres;

