-- Name: player_stats; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.player_stats (
    id integer NOT NULL,
    game_id integer,
    player_name character varying(255) NOT NULL,
    completions integer DEFAULT 0,
    pass_attempts integer DEFAULT 0,
    pass_yards integer DEFAULT 0,
    pass_tds integer DEFAULT 0,
    interceptions integer DEFAULT 0,
    rush_attempts integer DEFAULT 0,
    rush_yards integer DEFAULT 0,
    rush_tds integer DEFAULT 0,
    receptions integer DEFAULT 0,
    rec_yards integer DEFAULT 0,
    rec_tds integer DEFAULT 0,
    team_id integer,
    fumb integer DEFAULT 0,
    "position" character varying(10),
    fantasy_points numeric(6,2) GENERATED ALWAYS AS (round(((((((((((COALESCE(pass_yards, 0))::numeric * 0.04) + ((COALESCE(pass_tds, 0))::numeric * 4.0)) - ((COALESCE(interceptions, 0))::numeric * 2.0)) + ((COALESCE(rush_yards, 0))::numeric * 0.1)) + ((COALESCE(rush_tds, 0))::numeric * 6.0)) + ((COALESCE(receptions, 0))::numeric * 1.0)) + ((COALESCE(rec_yards, 0))::numeric * 0.1)) + ((COALESCE(rec_tds, 0))::numeric * 6.0)) - ((COALESCE(fumb, 0))::numeric * 2.0)), 2)) STORED,
    player_id integer,
    pass_comp_pct numeric(5,1),
    pass_rating numeric(5,1),
    pass_ypa numeric(5,1),
    pass_long integer,
    pass_sacks integer,
    rush_avg numeric(5,1),
    rush_btk integer,
    rush_yac integer,
    rush_long integer,
    rec_avg numeric(5,1),
    rec_rac integer,
    rec_rac_avg numeric(5,1),
    rec_long integer,
    line_source character varying(12),
    CONSTRAINT player_stats_line_source_check CHECK (((line_source)::text = ANY ((ARRAY['CAPTURED'::character varying, 'WEEKLY'::character varying, 'DISTRIBUTED'::character varying])::text[])))
);


