--
-- Name: game_stat_lines; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.game_stat_lines AS
 WITH ids AS (
         SELECT player_stats.game_id,
            player_stats.player_id
           FROM public.player_stats
          WHERE (player_stats.player_id IS NOT NULL)
        UNION
         SELECT game_stat_general.game_id,
            game_stat_general.player_id
           FROM public.game_stat_general
        UNION
         SELECT game_stat_blocking.game_id,
            game_stat_blocking.player_id
           FROM public.game_stat_blocking
        UNION
         SELECT game_stat_defense.game_id,
            game_stat_defense.player_id
           FROM public.game_stat_defense
        UNION
         SELECT game_stat_kicking.game_id,
            game_stat_kicking.player_id
           FROM public.game_stat_kicking
        UNION
         SELECT game_stat_punting.game_id,
            game_stat_punting.player_id
           FROM public.game_stat_punting
        UNION
         SELECT game_stat_kickreturn.game_id,
            game_stat_kickreturn.player_id
           FROM public.game_stat_kickreturn
        UNION
         SELECT game_stat_puntreturn.game_id,
            game_stat_puntreturn.player_id
           FROM public.game_stat_puntreturn
        )
 SELECT ids.game_id,
    gm.season,
    gm.week,
    ids.player_id,
    pl.player_name,
    pl.full_name,
    COALESCE(s.team_id, g.team_id, d.team_id, k.team_id, p.team_id, kr.team_id, pr.team_id, b.team_id) AS team_id,
    g.downs_played,
    s.completions,
    s.pass_attempts,
    s.pass_yards,
    s.pass_tds,
    s.interceptions,
    s.pass_comp_pct,
    s.pass_rating,
    s.pass_ypa,
    s.pass_long,
    s.pass_sacks,
    s.rush_attempts,
    s.rush_yards,
    s.rush_tds,
    s.fumb,
    s.rush_avg,
    s.rush_btk,
    s.rush_yac,
    s.rush_long,
    s.receptions,
    s.rec_yards,
    s.rec_tds,
    s.rec_avg,
    s.rec_rac,
    s.rec_rac_avg,
    s.rec_long,
    s.fantasy_points,
    b.sacks_allowed AS blk_sacks_allowed,
    d.solo AS def_solo,
    d.assists AS def_assists,
    d.tackles AS def_tackles,
    d.tfl AS def_tfl,
    d.sacks AS def_sacks,
    d.ints AS def_ints,
    d.int_yds AS def_int_yds,
    d.int_avg AS def_int_avg,
    d.int_long AS def_int_long,
    d.deflections AS def_deflections,
    d.forced_fumbles AS def_forced_fumbles,
    d.fumble_recoveries AS def_fumble_recoveries,
    d.fumble_yds AS def_fumble_yds,
    d.blocks AS def_blocks,
    d.safeties AS def_safeties,
    d.tds AS def_tds,
    k.fgm AS kick_fgm,
    k.fga AS kick_fga,
    k.fg_pct AS kick_fg_pct,
    k.fg_long AS kick_fg_long,
    k.fg_blocked AS kick_fg_blocked,
    k.xpm AS kick_xpm,
    k.xpa AS kick_xpa,
    k.xp_pct AS kick_xp_pct,
    k.xp_blocked AS kick_xp_blocked,
    k.fgm_29 AS kick_fgm_29,
    k.fga_29 AS kick_fga_29,
    k.fgm_39 AS kick_fgm_39,
    k.fga_39 AS kick_fga_39,
    k.fgm_49 AS kick_fgm_49,
    k.fga_49 AS kick_fga_49,
    k.fgm_50 AS kick_fgm_50,
    k.fga_50 AS kick_fga_50,
    k.kickoffs AS kick_kickoffs,
    k.touchbacks AS kick_touchbacks,
    p.punts AS punt_punts,
    p.yards AS punt_yards,
    p.average AS punt_average,
    p.net_yards AS punt_net_yards,
    p.net_average AS punt_net_average,
    p.blocked AS punt_blocked,
    p.inside_20 AS punt_inside_20,
    p.touchbacks AS punt_touchbacks,
    p.longest AS punt_longest,
    kr.returns AS kr_returns,
    kr.yards AS kr_yards,
    kr.average AS kr_average,
    kr.tds AS kr_tds,
    kr.longest AS kr_longest,
    pr.returns AS pr_returns,
    pr.yards AS pr_yards,
    pr.average AS pr_average,
    pr.tds AS pr_tds,
    pr.longest AS pr_longest
   FROM ((((((((((ids
     JOIN public.games gm ON ((gm.id = ids.game_id)))
     JOIN public.players pl ON ((pl.id = ids.player_id)))
     LEFT JOIN public.player_stats s ON (((s.game_id = ids.game_id) AND (s.player_id = ids.player_id))))
     LEFT JOIN public.game_stat_general g ON (((g.game_id = ids.game_id) AND (g.player_id = ids.player_id))))
     LEFT JOIN public.game_stat_blocking b ON (((b.game_id = ids.game_id) AND (b.player_id = ids.player_id))))
     LEFT JOIN public.game_stat_defense d ON (((d.game_id = ids.game_id) AND (d.player_id = ids.player_id))))
     LEFT JOIN public.game_stat_kicking k ON (((k.game_id = ids.game_id) AND (k.player_id = ids.player_id))))
     LEFT JOIN public.game_stat_punting p ON (((p.game_id = ids.game_id) AND (p.player_id = ids.player_id))))
     LEFT JOIN public.game_stat_kickreturn kr ON (((kr.game_id = ids.game_id) AND (kr.player_id = ids.player_id))))
     LEFT JOIN public.game_stat_puntreturn pr ON (((pr.game_id = ids.game_id) AND (pr.player_id = ids.player_id))));


