--
-- Name: league_top10; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.league_top10 AS
 SELECT ranked.id,
    ranked.category,
    ranked.value,
    ranked.holder,
    ranked.team_id,
    ranked.player_id,
    ranked.season,
    ranked.game_date,
    ranked.game_id,
    ranked.source,
    ranked.created_at,
    ranked.label,
    ranked.scope,
    ranked.subject,
    ranked.better,
    ranked.season_type,
    ranked.rank
   FROM ( SELECT e.id,
            e.category,
            e.value,
            e.holder,
            e.team_id,
            e.player_id,
            e.season,
            e.game_date,
            e.game_id,
            e.source,
            e.created_at,
            c.label,
            c.scope,
            c.subject,
            c.better,
            c.season_type,
            rank() OVER (PARTITION BY e.category ORDER BY
                CASE
                    WHEN ((c.better)::text = 'LOW'::text) THEN e.value
                    ELSE (- e.value)
                END) AS rank
           FROM (public.league_record_entries e
             JOIN public.record_categories c ON (((c.category)::text = (e.category)::text)))) ranked
  WHERE (ranked.rank <= 10);


ALTER TABLE public.league_top10 OWNER TO postgres;

--
-- Name: league_records; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.league_records AS
 WITH cands AS (
         SELECT fr.category,
            fr.value,
            fr.holder,
            fr.team_id,
            fr.player_id,
            fr.season,
            NULL::date AS game_date,
            NULL::integer AS game_id,
            fr.source
           FROM (public.franchise_records_current fr
             JOIN public.record_categories c_1 ON (((c_1.category)::text = (fr.category)::text)))
          WHERE (((c_1.scope)::text = 'SEASON'::text) AND ((c_1.coverage)::text = 'FULL'::text) AND ((c_1.season_type)::text = 'REGULAR'::text))
        UNION
         SELECT t.category,
            t.value,
            t.holder,
            t.team_id,
            t.player_id,
            t.season,
            t.game_date,
            t.game_id,
            t.source
           FROM public.league_top10 t
          WHERE (t.rank = 1)
        ), best AS (
         SELECT c_1.category,
                CASE
                    WHEN ((rc_1.better)::text = 'LOW'::text) THEN min(c_1.value)
                    ELSE max(c_1.value)
                END AS value
           FROM (cands c_1
             JOIN public.record_categories rc_1 ON (((rc_1.category)::text = (c_1.category)::text)))
          GROUP BY c_1.category, rc_1.better
        )
 SELECT DISTINCT ON (c.category, c.holder, c.season) c.category,
    rc.label,
    rc.scope,
    rc.subject,
    rc.season_type,
    c.value,
    c.holder,
    c.team_id,
    c.player_id,
    c.season,
    c.game_date,
    c.game_id,
    c.source
   FROM ((cands c
     JOIN best b ON ((((b.category)::text = (c.category)::text) AND (b.value = c.value))))
     JOIN public.record_categories rc ON (((rc.category)::text = (c.category)::text)))
  ORDER BY c.category, c.holder, c.season, c.game_date;


