-- Name: team_season_results; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.team_season_results (
    season integer NOT NULL,
    team_id integer NOT NULL,
    wins integer NOT NULL,
    losses integer NOT NULL,
    ties integer NOT NULL,
    points_for integer NOT NULL,
    points_against integer NOT NULL,
    division_place smallint NOT NULL,
    division_tiebreak text,
    conference_seed smallint,
    playoff_result character varying(16) NOT NULL,
    playoff_wins integer DEFAULT 0 NOT NULL,
    playoff_losses integer DEFAULT 0 NOT NULL,
    head_coach_id integer,
    gm_id integer,
    finalized_at timestamp with time zone DEFAULT now() NOT NULL,
    source character varying(8) DEFAULT 'CAPTURE'::character varying NOT NULL,
    CONSTRAINT team_season_results_conference_seed_check CHECK (((conference_seed >= 1) AND (conference_seed <= 7))),
    CONSTRAINT team_season_results_division_place_check CHECK (((division_place >= 1) AND (division_place <= 4))),
    CONSTRAINT team_season_results_playoff_result_check CHECK (((playoff_result)::text = ANY ((ARRAY['MISSED'::character varying, 'WILD_CARD'::character varying, 'DIVISIONAL'::character varying, 'CONFERENCE'::character varying, 'SUPER_BOWL_LOSS'::character varying, 'CHAMPION'::character varying])::text[])))
);


ALTER TABLE public.team_season_results OWNER TO postgres;

