    red_zone_def_pct numeric(5,1),
    penalties integer,
    penalty_yards integer,
    pass_rate_oe double precision,
    fourth_down_oe double precision,
    observed_pass_lean character varying(6),
    observed_fourth_down character varying(6),
    tendency_games integer,
    CONSTRAINT team_seasons_observed_fourth_down_check CHECK (((observed_fourth_down)::text = ANY ((ARRAY['Low'::character varying, 'Medium'::character varying, 'High'::character varying])::text[]))),
    CONSTRAINT team_seasons_observed_pass_lean_check CHECK (((observed_pass_lean)::text = ANY ((ARRAY['Low'::character varying, 'Medium'::character varying, 'High'::character varying])::text[])))
);


