--
-- Name: vw_fantasy_defense_vs_position; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_fantasy_defense_vs_position AS
 WITH game_def AS (
         SELECT
                CASE
                    WHEN (ps.team_id = g.home_team_id) THEN g.away_team_id
                    ELSE g.home_team_id
                END AS def_team_id,
            ps."position",
            g.season,
            ps.fantasy_points AS ppr_score
           FROM (public.player_stats ps
             JOIN public.games g ON ((ps.game_id = g.id)))
          WHERE ((g.status)::text = 'COMPLETED'::text)
        ), team_pos_totals AS (
         SELECT game_def.season,
            game_def.def_team_id,
            game_def."position",
            sum(game_def.ppr_score) AS total_allowed,
            avg(game_def.ppr_score) AS avg_allowed
           FROM game_def
          GROUP BY game_def.season, game_def.def_team_id, game_def."position"
        ), league_pos_benchmarks AS (
         SELECT team_pos_totals.season,
            team_pos_totals."position",
            min(team_pos_totals.total_allowed) AS min_allowed,
            max(team_pos_totals.total_allowed) AS max_allowed,
            avg(team_pos_totals.total_allowed) AS league_avg_allowed
           FROM team_pos_totals
          GROUP BY team_pos_totals.season, team_pos_totals."position"
        )
 SELECT tpt.season,
    tpt.def_team_id,
    t.abbreviation AS def_team_abbr,
    t.name AS def_team_name,
    tpt."position",
    tpt.total_allowed,
    tpt.avg_allowed,
    lpb.min_allowed,
    lpb.max_allowed,
    lpb.league_avg_allowed,
    (ntile(5) OVER (PARTITION BY tpt.season, tpt."position" ORDER BY tpt.total_allowed))::numeric AS matchup_stars
   FROM ((team_pos_totals tpt
     JOIN public.teams t ON ((tpt.def_team_id = t.id)))
     JOIN league_pos_benchmarks lpb ON (((tpt.season = lpb.season) AND ((tpt."position")::text = (lpb."position")::text))));


ALTER TABLE public.vw_fantasy_defense_vs_position OWNER TO postgres;

--
-- Name: vw_fantasy_scores; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_fantasy_scores AS
 SELECT ps.game_id,
    ps.player_name,
    ps.team_id,
    g.season,
    g.week,
    ps.fantasy_points AS ppr_score,
    ps.player_id
   FROM (public.player_stats ps
     JOIN public.games g ON ((ps.game_id = g.id)))
UNION ALL
 SELECT k.game_id,
    p.player_name,
    k.team_id,
    g.season,
    g.week,
    round((((((((((COALESCE(k.fgm_29, 0))::numeric * 3.0) + ((COALESCE(k.fgm_39, 0))::numeric * 3.5)) + ((COALESCE(k.fgm_49, 0))::numeric * 4.5)) + ((COALESCE(k.fgm_50, 0))::numeric * 5.5)) +
        CASE
            WHEN ((COALESCE(k.fgm, 0) > 0) AND (COALESCE(k.fg_long, 0) >= 30)) THEN (((k.fg_long)::numeric * 0.1) -
            CASE
                WHEN (k.fg_long >= 50) THEN 5.5
                WHEN (k.fg_long >= 40) THEN 4.5
                ELSE 3.5
            END)
            ELSE 0.0
        END) + ((COALESCE(k.xpm, 0))::numeric * 1.0)) - (((COALESCE(k.fga, 0) - COALESCE(k.fgm, 0)))::numeric * 1.0)) - (((COALESCE(k.xpa, 0) - COALESCE(k.xpm, 0)))::numeric * 1.0)), 2) AS ppr_score,
    k.player_id
   FROM ((public.game_stat_kicking k
     JOIN public.games g ON ((k.game_id = g.id)))
     JOIN public.players p ON ((p.id = k.player_id)))
UNION ALL
 SELECT g.id AS game_id,
    p.player_name,
    dst.team_id,
    g.season,
    g.week,
    round(((((((COALESCE(def.sacks, (0)::numeric) + ((2 * COALESCE(def.ints, (0)::bigint)))::numeric) + ((2 * COALESCE(def.fumble_recoveries, (0)::bigint)))::numeric) + ((6 * (COALESCE(def.tds, (0)::bigint) + COALESCE(ret.tds, (0)::bigint))))::numeric) + ((2 * COALESCE(def.safeties, (0)::bigint)))::numeric) + ((2 * COALESCE(def.blocks, (0)::bigint)))::numeric) + (
        CASE
            WHEN (
            CASE
                WHEN (g.home_team_id = dst.team_id) THEN g.away_score
                ELSE g.home_score
            END = 0) THEN 10
            WHEN (
            CASE
                WHEN (g.home_team_id = dst.team_id) THEN g.away_score
                ELSE g.home_score
            END <= 6) THEN 7
            WHEN (
            CASE
                WHEN (g.home_team_id = dst.team_id) THEN g.away_score
                ELSE g.home_score
            END <= 13) THEN 4
            WHEN (
            CASE
                WHEN (g.home_team_id = dst.team_id) THEN g.away_score
                ELSE g.home_score
            END <= 20) THEN 1
            WHEN (
            CASE
                WHEN (g.home_team_id = dst.team_id) THEN g.away_score
                ELSE g.home_score
            END <= 27) THEN 0
            WHEN (
            CASE
                WHEN (g.home_team_id = dst.team_id) THEN g.away_score
                ELSE g.home_score
            END <= 34) THEN '-1'::integer
            ELSE '-4'::integer
        END)::numeric), 2) AS ppr_score,
    dst.player_id
   FROM ((((public.player_seasons dst
     JOIN public.players p ON ((p.id = dst.player_id)))
     JOIN public.games g ON (((g.season = dst.season) AND ((g.status)::text = 'COMPLETED'::text) AND ((g.home_team_id = dst.team_id) OR (g.away_team_id = dst.team_id)))))
     LEFT JOIN ( SELECT game_stat_defense.game_id,
            game_stat_defense.team_id,
            sum(game_stat_defense.sacks) AS sacks,
            sum(game_stat_defense.ints) AS ints,
            sum(game_stat_defense.fumble_recoveries) AS fumble_recoveries,
            sum(game_stat_defense.tds) AS tds,
            sum(game_stat_defense.safeties) AS safeties,
            sum(game_stat_defense.blocks) AS blocks
           FROM public.game_stat_defense
          GROUP BY game_stat_defense.game_id, game_stat_defense.team_id) def ON (((def.game_id = g.id) AND (def.team_id = dst.team_id))))
     LEFT JOIN ( SELECT r.game_id,
            r.team_id,
            sum(r.tds) AS tds
           FROM ( SELECT game_stat_kickreturn.game_id,
                    game_stat_kickreturn.team_id,
                    game_stat_kickreturn.tds
                   FROM public.game_stat_kickreturn
                UNION ALL
                 SELECT game_stat_puntreturn.game_id,
                    game_stat_puntreturn.team_id,
                    game_stat_puntreturn.tds
                   FROM public.game_stat_puntreturn) r
          GROUP BY r.game_id, r.team_id) ret ON (((ret.game_id = g.id) AND (ret.team_id = dst.team_id))))
  WHERE ((dst."position")::text = 'DEF'::text);


ALTER TABLE public.vw_fantasy_scores OWNER TO postgres;

--
-- Name: vw_gm_profiles; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_gm_profiles AS
 SELECT g.id AS gm_id,
    g.team_id,
    t.abbreviation,
    t.city,
    t.name AS team_name,
    g.gm_name,
    g.bio,
    g.voice,
    g.bio_source,
    g.start_season,
    g.risk_appetite,
    g.aggressiveness,
    g.pick_affinity,
    g.youth_bias,
    g.position_bias,
    ls.current_season AS season,
    s.direction,
    s.direction_score,
    s.direction_week,
    s.needs,
    s.surplus,
    s.urgent_need,
    s.fo_quality,
    s.fo_quality_inputs,
    s.fo_quality_at,
    COALESCE(st.user_controlled, false) AS user_controlled,
    COALESCE(st.suggestions_on, true) AS suggestions_on
   FROM ((((public.gm_profiles g
     JOIN public.teams t ON ((t.id = g.team_id)))
     CROSS JOIN public.league_state ls)
     LEFT JOIN public.gm_team_seasons s ON (((s.team_id = g.team_id) AND (s.season = ls.current_season))))
     LEFT JOIN public.gm_team_settings st ON ((st.team_id = g.team_id)))
  WHERE ((g.end_season IS NULL) AND (ls.id = 1));


ALTER TABLE public.vw_gm_profiles OWNER TO postgres;

--
-- Name: vw_scout_board_public; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_scout_board_public AS
 SELECT c.draft_season,
    c.step,
    c.season,
    c.week,
    c.stage,
    c.prospect_key,
    c.grade,
    c.rank,
    c.round_label,
    c.delta_grade,
    c.delta_rank,
    d.full_name,
    d."position",
    d.college,
    d.height_in,
    d.weight,
    d.age,
    sp.class_year,
    sp.conference,
    sp.status,
    ( SELECT e.headline
           FROM public.scout_events e
          WHERE ((e.draft_season = c.draft_season) AND (e.step = c.step) AND (e.prospect_key = c.prospect_key) AND ((e.kind)::text <> 'VISIT'::text))
          ORDER BY (abs(e.impact)) DESC NULLS LAST, e.id
         LIMIT 1) AS top_headline
   FROM ((public.scout_consensus c
     JOIN public.scout_prospects sp ON (((sp.draft_season = c.draft_season) AND (sp.prospect_key = c.prospect_key))))
     LEFT JOIN public.draft_prospects d ON ((d.id = sp.prospect_id)));


ALTER TABLE public.vw_scout_board_public OWNER TO postgres;

--
-- Name: vw_team_cap_sheet; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_team_cap_sheet AS
 SELECT c.team_id,
    t.abbreviation,
    c.season,
    c.id AS contract_id,
    c.player_id,
    p.player_name,
    ps."position",
    c.length,
    c.years_remaining,
    ((c.season + c.years_remaining) - 1) AS contract_end_season,
    c.total_value,
    c.bonus,
    c.cut_savings,
    c.cut_penalty,
    c.no_trade_clause,
    c.incentive,
    ( SELECT y.cap_hit
           FROM public.player_contract_years y
          WHERE ((y.contract_id = c.id) AND (y.year = c.season))) AS cap_hit_y0,
    ( SELECT y.cap_hit
           FROM public.player_contract_years y
          WHERE ((y.contract_id = c.id) AND (y.year = (c.season + 1)))) AS cap_hit_y1,
    ( SELECT y.cap_hit
           FROM public.player_contract_years y
          WHERE ((y.contract_id = c.id) AND (y.year = (c.season + 2)))) AS cap_hit_y2,
    ( SELECT y.cap_hit
           FROM public.player_contract_years y
          WHERE ((y.contract_id = c.id) AND (y.year = (c.season + 3)))) AS cap_hit_y3,
    ( SELECT y.cap_hit
           FROM public.player_contract_years y
          WHERE ((y.contract_id = c.id) AND (y.year = (c.season + 4)))) AS cap_hit_y4,
    tc.cap,
    tc.adjusted_cap,
    tc.cap_space,
    tc.total_spend,
    tc.next_rookie_reserve
   FROM ((((public.player_contracts c
     JOIN public.teams t ON ((t.id = c.team_id)))
     JOIN public.players p ON ((p.id = c.player_id)))
     LEFT JOIN public.player_seasons ps ON (((ps.player_id = c.player_id) AND (ps.season = c.season))))
     LEFT JOIN public.team_cap_seasons tc ON (((tc.team_id = c.team_id) AND (tc.season = c.season))))
  WHERE ((c.status)::text = 'ACTIVE'::text);


ALTER TABLE public.vw_team_cap_sheet OWNER TO postgres;

